def number_legacy_receipts(apps, schema_editor):
    """Payments recorded before receipts existed get a receipt number too."""
    Payment = apps.get_model("fees", "Payment")
    for payment in Payment.objects.filter(receipt_number__isnull=True):
        payment.receipt_number = f"RC-{payment.pk:06d}"
        payment.save(update_fields=["receipt_number"])


